import type { LucideIcon } from 'lucide-react'
import {
  BarChart3,
  Building2,
  CreditCard,
  FileText,
  FlaskConical,
  Globe,
  Palette,
  Plug,
  Scissors,
  Shield,
  Tag,
  Tags,
  UserCircle,
  Users,
} from 'lucide-react'

type VisibilityRule = (permissions: ReadonlySet<string>) => boolean

export interface SettingsNavItem {
  label: string
  href: string
  icon: LucideIcon
  badge?: 'danger'
}

export interface SettingsNavGroup {
  label: string
  items: SettingsNavItem[]
}

interface SettingsNavItemConfig extends SettingsNavItem {
  isVisible?: VisibilityRule
}

interface SettingsNavGroupConfig {
  label: string
  items: SettingsNavItemConfig[]
}

const BILLING_SETTINGS_PERMISSIONS = [
  'settings.billing',
  'billing.view',
  'billing.cancel_studio',
] as const

function hasPermission(
  permissions: ReadonlySet<string>,
  permission: string,
): boolean {
  return permissions.has(permission)
}

function hasAnyPermission(
  permissions: ReadonlySet<string>,
  requiredPermissions: readonly string[],
): boolean {
  return requiredPermissions.some((permission) => hasPermission(permissions, permission))
}

function visibleWith(permission: string): VisibilityRule {
  return (permissions) => hasPermission(permissions, permission)
}

function visibleWithAny(requiredPermissions: readonly string[]): VisibilityRule {
  return (permissions) => hasAnyPermission(permissions, requiredPermissions)
}

const SETTINGS_NAV_CONFIG: SettingsNavGroupConfig[] = [
  {
    label: 'Studio',
    items: [
      {
        label: 'Profile',
        href: '/settings/studio/profile',
        icon: Building2,
        isVisible: visibleWith('settings.studio'),
      },
      {
        label: 'Branding',
        href: '/settings/studio/branding',
        icon: Palette,
        isVisible: visibleWith('settings.branding'),
      },
      {
        label: 'Services',
        href: '/settings/studio/services',
        icon: Scissors,
        isVisible: visibleWith('settings.services'),
      },
      {
        label: 'Booking policies',
        href: '/settings/studio/policies',
        icon: FileText,
        isVisible: visibleWith('settings.studio'),
      },
      {
        label: 'Ink registry',
        href: '/settings/studio/ink-registry',
        icon: FlaskConical,
        isVisible: visibleWith('settings.studio'),
      },
      {
        label: 'Style tags',
        href: '/settings/studio/style-tags',
        icon: Tags,
        isVisible: visibleWith('settings.studio'),
      },
      {
        label: 'Client tags',
        href: '/settings/tags',
        icon: Tag,
        isVisible: visibleWith('settings.studio'),
      },
      {
        label: 'Booking page',
        href: '/settings/studio/booking-page',
        icon: Globe,
        isVisible: visibleWith('settings.booking_page'),
      },
    ],
  },
  {
    label: 'Team',
    items: [
      {
        label: 'Members',
        href: '/settings/team/members',
        icon: Users,
        isVisible: visibleWith('settings.team'),
      },
      {
        label: 'Roles & permissions',
        href: '/settings/team/permissions',
        icon: Shield,
        isVisible: visibleWith('settings.team'),
      },
    ],
  },
  {
    label: 'Subscription',
    items: [
      {
        label: 'Plan & billing',
        href: '/settings/subscription/billing',
        icon: CreditCard,
        isVisible: visibleWithAny(BILLING_SETTINGS_PERMISSIONS),
      },
      {
        label: 'Usage',
        href: '/settings/subscription/usage',
        icon: BarChart3,
        isVisible: visibleWithAny(BILLING_SETTINGS_PERMISSIONS),
      },
    ],
  },
  {
    label: 'Integrations',
    items: [
      {
        label: 'Connected apps',
        href: '/settings/integrations',
        icon: Plug,
        isVisible: visibleWith('settings.integrations'),
      },
    ],
  },
  {
    label: 'Account',
    items: [
      { label: 'My profile', href: '/settings/account/profile', icon: UserCircle },
      {
        label: 'Advanced',
        href: '/settings/account/advanced',
        icon: Shield,
        badge: 'danger',
      },
    ],
  },
]

export function getVisibleSettingsNavGroups(
  permissions: ReadonlySet<string>,
): SettingsNavGroup[] {
  return SETTINGS_NAV_CONFIG
    .map((group) => ({
      label: group.label,
      items: group.items.filter((item) => item.isVisible?.(permissions) ?? true),
    }))
    .filter((group) => group.items.length > 0)
}

export function resolveSettingsLandingHref(permissions: ReadonlySet<string>): string {
  if (hasPermission(permissions, 'settings.studio')) {
    return '/settings/studio/profile'
  }

  if (hasPermission(permissions, 'settings.branding')) {
    return '/settings/studio/branding'
  }

  if (hasPermission(permissions, 'settings.services')) {
    return '/settings/studio/services'
  }

  if (hasPermission(permissions, 'settings.booking_page')) {
    return '/settings/studio/booking-page'
  }

  if (hasPermission(permissions, 'settings.team')) {
    return '/settings/team/members'
  }

  if (hasAnyPermission(permissions, BILLING_SETTINGS_PERMISSIONS)) {
    return '/settings/subscription/billing'
  }

  if (hasPermission(permissions, 'settings.integrations')) {
    return '/settings/integrations'
  }

  return '/settings/account/profile'
}

