'use client'

import { Lock } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import type { PlanTier } from '@/lib/dodo/client'

const PLAN_LABELS: Record<PlanTier, string> = {
  solo: 'Solo',
  studio: 'Studio',
  pro: 'Pro',
  enterprise: 'Enterprise',
}

// ---------------------------------------------------------------------------
// Inline variant — wraps child content with a lock overlay
// ---------------------------------------------------------------------------

interface UpgradeGateInlineProps {
  requiredPlan: PlanTier
  feature?: string
  onUpgrade?: () => void
  children: React.ReactNode
}

export function UpgradeGateInline({ requiredPlan, feature, onUpgrade, children }: UpgradeGateInlineProps) {
  return (
    <div className="relative">
      <div className="pointer-events-none select-none opacity-40">{children}</div>
      <div className="upgrade-gate-block absolute inset-0 rounded-lg flex flex-col items-center justify-center gap-2 p-4">
        <Lock className="h-5 w-5 text-rust" />
        <p className="text-xs font-medium text-center">
          {feature ? `${feature} requires ` : 'Requires '}
          <span className="text-rust font-semibold">{PLAN_LABELS[requiredPlan]}</span> plan
        </p>
        {onUpgrade && (
          <Button
            size="sm"
            variant="outline"
            onClick={onUpgrade}
            className="h-7 text-xs border-rust/40 text-rust hover:bg-rust-tint"
          >
            Upgrade
          </Button>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Page-block variant — full-width locked state for gated pages/sections
// ---------------------------------------------------------------------------

interface UpgradeGatePageBlockProps {
  requiredPlan: PlanTier
  feature: string
  description?: string
  onUpgrade?: () => void
}

export function UpgradeGatePageBlock({ requiredPlan, feature, description, onUpgrade }: UpgradeGatePageBlockProps) {
  return (
    <div className="upgrade-gate-block rounded-xl p-12 flex flex-col items-center justify-center gap-4 text-center min-h-[280px]">
      <div className="rounded-full bg-rust-tint border border-rust/20 p-4">
        <Lock className="h-6 w-6 text-rust" />
      </div>
      <div className="space-y-1">
        <h3 className="text-base font-semibold">{feature}</h3>
        <p className="text-sm text-muted-foreground max-w-sm">
          {description ?? `This feature is available on the ${PLAN_LABELS[requiredPlan]} plan and above.`}
        </p>
      </div>
      <div className="flex items-center gap-2">
        <span className="text-xs text-muted-foreground">Available on</span>
        <span className="inline-flex items-center rounded-full bg-rust-tint text-rust border border-rust/30 px-2.5 py-0.5 text-xs font-bold uppercase tracking-[0.08em]">
          {PLAN_LABELS[requiredPlan]}+
        </span>
      </div>
      {onUpgrade && (
        <Button
          onClick={onUpgrade}
        >
          Upgrade to {PLAN_LABELS[requiredPlan]}
        </Button>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Modal variant
// ---------------------------------------------------------------------------

interface UpgradeGateModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  requiredPlan: PlanTier
  feature: string
  description?: string
  onUpgrade?: () => void
}

export function UpgradeGateModal({
  open,
  onOpenChange,
  requiredPlan,
  feature,
  description,
  onUpgrade,
}: UpgradeGateModalProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <div className="flex items-center gap-3 mb-2">
            <div className="rounded-full bg-rust-tint border border-rust/20 p-3">
              <Lock className="h-5 w-5 text-rust" />
            </div>
            <DialogTitle className="text-base">{feature}</DialogTitle>
          </div>
          <DialogDescription>
            {description ?? `This feature requires the ${PLAN_LABELS[requiredPlan]} plan or higher.`}
          </DialogDescription>
        </DialogHeader>
        <div className="flex items-center gap-3 pt-2">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            className="flex-1"
          >
            Maybe later
          </Button>
          {onUpgrade && (
            <Button
              onClick={() => { onUpgrade(); onOpenChange(false) }}
              className="flex-1"
            >
              Upgrade to {PLAN_LABELS[requiredPlan]}
            </Button>
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageShellProps {
  children: ReactNode
  /**
   * Opt out of default padding for full-height layouts (Calendar, Messages).
   * The page is responsible for its own scroll container + internal padding.
   */
  fullHeight?: boolean
  /** Max content width cap. Default `1440`. Pass `false` to disable the cap. */
  maxWidth?: number | false
  /** Extra classes applied to the outer wrapper. */
  className?: string
  /** Extra classes applied to the inner padded container (ignored when fullHeight). */
  innerClassName?: string
}

/**
 * S18 — Branded page container.
 *
 * Enforces the same gutter + vertical rhythm the TodayClient established as the
 * gold standard: `px-4 sm:px-6 lg:px-8 pt-6 pb-10`, `max-w-[1440px]` cap,
 * background token `--color-page-bg`. Every authenticated page should wrap its
 * content in `<PageShell>`. Full-height layouts (Calendar, Messages) pass
 * `fullHeight` to skip the default padding and handle scroll internally.
 */
export function PageShell({
  children,
  fullHeight = false,
  maxWidth = 1440,
  className,
  innerClassName,
}: PageShellProps) {
  if (fullHeight) {
    return (
      <div className={cn('flex min-h-0 flex-1 flex-col', className)}>
        {children}
      </div>
    )
  }

  return (
    <div
      className={cn(
        // Base page background + dark-aware radial highlight (top-right) + rust
        // whisper (bottom-left). Both tokens flip between light (bone highlight,
        // faint rust) and dark (subtle rust warmth, slightly stronger rust) so
        // the page keeps tonal depth in either theme without blowing out.
        'relative flex min-h-full flex-col bg-[var(--color-page-bg)]',
        'before:pointer-events-none before:absolute before:inset-0',
        'before:bg-[radial-gradient(ellipse_at_top_right,_var(--color-page-highlight)_0%,_transparent_55%)]',
        'after:pointer-events-none after:absolute after:inset-0',
        'after:bg-[radial-gradient(circle_at_bottom_left,_var(--color-page-whisper)_0%,_transparent_45%)]',
        className,
      )}
    >
      <div
        style={
          maxWidth !== false && maxWidth !== 1440
            ? { maxWidth: `${maxWidth}px` }
            : undefined
        }
        className={cn(
          // S24 page-chrome rhythm — every direct child sits on a 24px vertical
          // cadence: PageHeader → PageViews → PageToolbar → content. Sub-24px
          // spacing nests inside a child `flex flex-col gap-*` container.
          // Flex gap (not margin) so children's own mt-* never fights the rhythm.
          'relative z-10 mx-auto w-full flex-1 px-4 pb-10 pt-6 sm:px-6 lg:px-8',
          'flex flex-col gap-6',
          maxWidth === 1440 && 'max-w-[1440px]',
          innerClassName,
        )}
      >
        {children}
      </div>
    </div>
  )
}
