import Link from 'next/link'
import { ArrowLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb'

interface BreadcrumbItemDef {
  label: string
  href?: string // absent = current page (not a link)
}

interface PageHeaderProps {
  title: string
  description?: string         // replaces old `subtitle`
  actions?: React.ReactNode    // replaces old `right`
  breadcrumb?: BreadcrumbItemDef[]
  backHref?: string            // renders a back button/link before title
  className?: string
}

export function PageHeader({
  title,
  description,
  actions,
  breadcrumb,
  backHref,
  className,
}: PageHeaderProps) {
  return (
    <div
      className={cn(
        'relative flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between',
        // Hairline rust divider — brand signature, anchored flush at the bottom
        // of the header's own box (not leaking into sibling space). `pb-3` gives
        // the hairline breathing room under the description; the 24px rhythm to
        // the next zone is owned by PageShell's `space-y-6`.
        'pb-3',
        "after:pointer-events-none after:absolute after:bottom-0 after:left-0 after:h-px after:w-10 after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.6),_transparent)]",
        className,
      )}
    >
      {/* Left column */}
      <div className="flex flex-col gap-1 min-w-0">
        {/* Back link */}
        {backHref && (
          <Link
            href={backHref}
            className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-1"
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
            Back
          </Link>
        )}

        {/* Breadcrumb */}
        {breadcrumb && breadcrumb.length > 0 && (
          <Breadcrumb className="mb-2">
            <BreadcrumbList className="text-[13px]">
              {breadcrumb.map((item, i) => {
                const isLast = i === breadcrumb.length - 1
                return (
                  <BreadcrumbItem key={i}>
                    {isLast ? (
                      <BreadcrumbPage className="text-[13px]">{item.label}</BreadcrumbPage>
                    ) : (
                      <>
                        <BreadcrumbLink
                          render={<Link href={item.href ?? '#'} className="text-[13px]" />}
                        >
                          {item.label}
                        </BreadcrumbLink>
                        <BreadcrumbSeparator>
                          <ChevronRight className="size-3" aria-hidden="true" />
                        </BreadcrumbSeparator>
                      </>
                    )}
                  </BreadcrumbItem>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
        )}

        {/* Title — Instrument Serif per brand book */}
        <h1 className="font-display text-[36px] leading-[1.1] text-foreground truncate">
          {title}
        </h1>

        {/* Description */}
        {description && (
          <p className="text-sm text-stone-brand mt-1.5">
            {description}
          </p>
        )}
      </div>

      {/* Actions slot */}
      {actions && (
        <div className="flex shrink-0 items-center gap-2 mt-4 sm:mt-0">
          {actions}
        </div>
      )}
    </div>
  )
}

