// Export SmartReplyAction type for UI consumers
export type { SmartReplyAction }

// ─── updateStudioMessagingAction ──────────────────────────────────────────────

const BusinessHoursSchema = z.record(
  z.string(),
  z.object({ open: z.string(), close: z.string() }),
)

const UpdateStudioMessagingSchema = z.object({
  signature: z.string().max(2000).optional(),
  businessHours: BusinessHoursSchema.optional(),
  tone: z.enum(['casual', 'formal']).optional(),
})

export async function updateStudioMessagingAction(
  input: z.infer<typeof UpdateStudioMessagingSchema>,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = UpdateStudioMessagingSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const patch: Record<string, unknown> = {}
  if (parsed.data.signature !== undefined) patch['email_signature'] = parsed.data.signature
  if (parsed.data.businessHours !== undefined) patch['messaging_business_hours'] = parsed.data.businessHours
  if (parsed.data.tone !== undefined) patch['messaging_tone'] = parsed.data.tone

  if (Object.keys(patch).length === 0) return { ok: true }

  try {
    const supabase = await (await import('@/lib/supabase/server')).createClient()
    const { error } = await supabase
      .from('studios')
      .update(patch)
      .eq('id', authUser.studioId)
    if (error) throw error
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err }, 'updateStudioMessagingAction: failed')
    return { ok: false, error: 'Failed to save messaging settings' }
  }
}

