import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { createClient } from '@/lib/supabase/server'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { listMessageTemplates, listAutoReplyRules } from '@/lib/messaging/queries'
import { MessagingSettingsClient } from './MessagingSettingsClient'
import type { Database } from '@/lib/supabase/types'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import Link from 'next/link'
import { Button } from '@/components/ui/button'

export const metadata: Metadata = {
  title: 'Messaging Settings — InkOS',
}

type StudioMessagingData = Pick<
  Database['public']['Tables']['studios']['Row'],
  | 'id'
  | 'name'
  | 'email_signature'
  | 'messaging_business_hours'
  | 'messaging_tone'
  | 'messaging_connected_channels'
>

const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const

export default async function MessagingSettingsPage() {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const supabase = await createClient()

  // Feature gate — omnichannel_inbox requires Studio+
  try {
    await requireFeatureRpc(supabase, studioId, 'omnichannel_inbox')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return (
        <div className="space-y-6">
          <div>
            <h2 className="text-2xl font-bold text-foreground">Messaging</h2>
            <p className="text-sm text-muted-foreground mt-1">
              Auto-replies, templates, signatures, and channel connections.
            </p>
          </div>
          <UpgradeGatePageBlock
            requiredPlan="studio"
            feature="Messaging Settings"
            description="Auto-reply rules, message templates, email signatures, and channel connections require the Studio plan or above."
            onUpgrade={undefined}
          />
          <p className="text-sm text-muted-foreground">
            <Link href="/settings/subscription/billing" className="underline underline-offset-4">
              View billing settings
            </Link>{' '}
            to upgrade.
          </p>
        </div>
      )
    }
    redirect('/dashboard')
  }

  // Parallel data fetch
  const [templatesResult, rulesResult, studioResult] = await Promise.all([
    listMessageTemplates(studioId),
    listAutoReplyRules(studioId),
    supabase
      .from('studios')
      .select('id, name, email_signature, messaging_business_hours, messaging_tone, messaging_connected_channels')
      .eq('id', studioId)
      .single(),
  ])

  const studio = studioResult.data as StudioMessagingData | null
  if (!studio) redirect('/dashboard')

  // Derive channel connection status from env
  const channelStatus = [
    {
      key: 'sms' as const,
      connected: !!process.env.TWILIO_ACCOUNT_SID,
      providerLabel: 'via Twilio',
    },
    {
      key: 'email' as const,
      connected: !!process.env.RESEND_API_KEY,
      providerLabel: 'via Resend',
    },
    {
      key: 'instagram' as const,
      connected: false,
      providerLabel: 'via Meta',
    },
    {
      key: 'whatsapp' as const,
      connected: false,
      providerLabel: 'via Meta',
    },
    {
      key: 'webchat' as const,
      connected: false,
      providerLabel: 'via InkOS widget',
    },
    {
      key: 'phone' as const,
      connected: !!process.env.TWILIO_ACCOUNT_SID,
      providerLabel: 'via Twilio',
    },
  ]

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-foreground">Messaging</h2>
        <p className="text-sm text-muted-foreground mt-1">
          Auto-replies, templates, signatures, and channel connections.
        </p>
      </div>

      <MessagingSettingsClient
        templates={templatesResult}
        rules={rulesResult}
        studio={studio}
        channelStatus={channelStatus}
      />
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { Textarea } from '@/components/ui/textarea'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { ChannelConnectionsCard } from '@/components/settings/messaging/ChannelConnectionsCard'
import { AutoReplyRulesCard } from '@/components/settings/messaging/AutoReplyRulesCard'
import { TemplatesTable } from '@/components/settings/messaging/TemplatesTable'
import { updateStudioMessagingAction } from '@/app/(app)/messages/actions'
import type { MessageTemplate, AutoReplyRule } from '@/lib/supabase/types'
import type { AutoReplyRuleWithTemplate } from '@/lib/messaging/queries'
import type { Database } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────────────────────

export type ChannelStatus = {
  key: 'sms' | 'email' | 'instagram' | 'whatsapp' | 'webchat' | 'phone'
  connected: boolean
  providerLabel: string
}

type StudioMessagingData = Pick<
  Database['public']['Tables']['studios']['Row'],
  | 'id'
  | 'name'
  | 'email_signature'
  | 'messaging_business_hours'
  | 'messaging_tone'
  | 'messaging_connected_channels'
>

interface MessagingSettingsClientProps {
  templates: MessageTemplate[]
  rules: AutoReplyRuleWithTemplate[]
  studio: StudioMessagingData
  channelStatus: ChannelStatus[]
}

// ─── Business hours helpers ───────────────────────────────────────────────────

const DAYS = [
  { key: 'monday', label: 'Monday' },
  { key: 'tuesday', label: 'Tuesday' },
  { key: 'wednesday', label: 'Wednesday' },
  { key: 'thursday', label: 'Thursday' },
  { key: 'friday', label: 'Friday' },
  { key: 'saturday', label: 'Saturday' },
  { key: 'sunday', label: 'Sunday' },
] as const

type DayKey = typeof DAYS[number]['key']

interface DayHours {
  open: string
  close: string
}

function parseBusinessHours(
  raw: Record<string, { open: string; close: string }> | null,
): Record<DayKey, DayHours | null> {
  const defaults: Record<DayKey, DayHours | null> = {
    monday: { open: '09:00', close: '18:00' },
    tuesday: { open: '09:00', close: '18:00' },
    wednesday: { open: '09:00', close: '18:00' },
    thursday: { open: '09:00', close: '18:00' },
    friday: { open: '09:00', close: '18:00' },
    saturday: { open: '10:00', close: '16:00' },
    sunday: null,
  }
  if (!raw) return defaults
  for (const day of DAYS) {
    const v = raw[day.key]
    defaults[day.key] = v ? { open: v.open, close: v.close } : null
  }
  return defaults
}

// ─── Signature card ───────────────────────────────────────────────────────────

function SignatureCard({ initial }: { initial: string | null }) {
  const [value, setValue] = useState(initial ?? '')
  const [pending, startTransition] = useTransition()

  const save = () => {
    startTransition(async () => {
      const res = await updateStudioMessagingAction({ signature: value })
      if (res.ok) {
        toast.success('Signature saved')
      } else {
        toast.error(res.error ?? 'Failed to save signature')
      }
    })
  }

  return (
    <div className="rounded-xl border border-border bg-background p-6 shadow-card space-y-4">
      <div>
        <h3 className="text-sm font-bold text-foreground">Email Signature</h3>
        <p className="text-[13px] text-muted-foreground mt-0.5">
          Appended to every outbound email message from this studio.
        </p>
      </div>
      <div className="space-y-1.5">
        <Label htmlFor="messaging-signature" className="sr-only">Signature</Label>
        <Textarea
          id="messaging-signature"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          rows={5}
          placeholder="— Your Studio Name&#10;📍 123 Main St · City, State&#10;📞 (555) 000-0000"
          className="resize-none font-mono text-[13px]"
          maxLength={2000}
        />
        <p className="text-[11px] text-muted-foreground tabular-nums">
          {value.length} / 2000 characters
        </p>
      </div>
      <div className="flex justify-end">
        <Button size="sm" onClick={save} disabled={pending}>
          {pending ? 'Saving...' : 'Save signature'}
        </Button>
      </div>
    </div>
  )
}

// ─── Business hours card ──────────────────────────────────────────────────────

function BusinessHoursCard({
  initial,
}: {
  initial: Record<string, { open: string; close: string }> | null
}) {
  const [hours, setHours] = useState(() => parseBusinessHours(initial))
  const [pending, startTransition] = useTransition()

  const setDayHours = (day: DayKey, field: 'open' | 'close', value: string) => {
    setHours((prev) => ({
      ...prev,
      [day]: prev[day] ? { ...prev[day]!, [field]: value } : { open: '09:00', close: '18:00', [field]: value },
    }))
  }

  const toggleDay = (day: DayKey) => {
    setHours((prev) => ({
      ...prev,
      [day]: prev[day] ? null : { open: '09:00', close: '18:00' },
    }))
  }

  const save = () => {
    const payload: Record<string, { open: string; close: string }> = {}
    for (const { key } of DAYS) {
      const v = hours[key]
      if (v) payload[key] = v
    }
    startTransition(async () => {
      const res = await updateStudioMessagingAction({ businessHours: payload })
      if (res.ok) {
        toast.success('Business hours saved')
      } else {
        toast.error(res.error ?? 'Failed to save business hours')
      }
    })
  }

  return (
    <div className="rounded-xl border border-border bg-background p-6 shadow-card space-y-4">
      <div>
        <h3 className="text-sm font-bold text-foreground">Business Hours</h3>
        <p className="text-[13px] text-muted-foreground mt-0.5">
          Off-hours auto-replies only fire outside these windows.
        </p>
      </div>

      <div className="space-y-0">
        {DAYS.map(({ key, label }, i) => {
          const isOpen = hours[key] !== null
          return (
            <div
              key={key}
              className={`flex items-center gap-3 py-2.5 ${i > 0 ? 'border-t border-border/40' : ''}`}
            >
              <button
                type="button"
                role="checkbox"
                aria-checked={isOpen}
                aria-label={`Toggle ${label}`}
                onClick={() => toggleDay(key)}
                className={`h-4 w-4 rounded border transition-colors shrink-0 ${
                  isOpen
                    ? 'bg-foreground border-foreground'
                    : 'bg-transparent border-border'
                }`}
              />
              <span className="w-[100px] text-[13px] font-medium text-foreground shrink-0">
                {label}
              </span>
              {isOpen ? (
                <div className="flex items-center gap-2">
                  <input
                    type="time"
                    value={hours[key]?.open ?? '09:00'}
                    onChange={(e) => setDayHours(key, 'open', e.target.value)}
                    aria-label={`${label} open time`}
                    className="h-8 rounded-md border border-border bg-background px-2 text-[13px] text-foreground focus:outline-none focus:ring-1 focus:ring-ring"
                  />
                  <span className="text-[13px] text-muted-foreground">to</span>
                  <input
                    type="time"
                    value={hours[key]?.close ?? '18:00'}
                    onChange={(e) => setDayHours(key, 'close', e.target.value)}
                    aria-label={`${label} close time`}
                    className="h-8 rounded-md border border-border bg-background px-2 text-[13px] text-foreground focus:outline-none focus:ring-1 focus:ring-ring"
                  />
                </div>
              ) : (
                <span className="text-[13px] text-muted-foreground">Closed</span>
              )}
            </div>
          )
        })}
      </div>

      <div className="flex justify-end pt-2">
        <Button size="sm" onClick={save} disabled={pending}>
          {pending ? 'Saving...' : 'Save hours'}
        </Button>
      </div>
    </div>
  )
}

// ─── Main ─────────────────────────────────────────────────────────────────────

export function MessagingSettingsClient({
  templates,
  rules,
  studio,
  channelStatus,
}: MessagingSettingsClientProps) {
  return (
    <div className="space-y-6">
      <ChannelConnectionsCard channels={channelStatus} />
      <AutoReplyRulesCard rules={rules} templates={templates} />
      <TemplatesTable templates={templates} />
      <SignatureCard initial={studio.email_signature} />
      <BusinessHoursCard initial={studio.messaging_business_hours} />
    </div>
  )
}

'use client'

