'use client'

import { useState, useEffect } from 'react'
import { z } from 'zod'
import { toast } from 'sonner'
import { ActionSheet } from '@/components/shared/ActionSheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { createRuleAction, updateRuleAction } from '@/app/(app)/messages/actions'
import type { MessageTemplate } from '@/lib/supabase/types'
import type { AutoReplyRuleWithTemplate } from '@/lib/messaging/queries'

// ─── Schema ───────────────────────────────────────────────────────────────────

const RuleFormSchema = z.object({
  trigger_type: z.enum(['new_inquiry', 'missed_call', 'deposit_paid', 'keyword']),
  keyword: z.string().max(100).optional(),
  template_id: z.string().uuid('Select a template'),
  cooldown_minutes: z.number().int().min(0).max(1440),
  tone: z.enum(['casual', 'formal']),
  enabled: z.boolean(),
})

type RuleFormValues = z.infer<typeof RuleFormSchema>

const TRIGGER_LABELS: Record<RuleFormValues['trigger_type'], string> = {
  new_inquiry: 'New inquiry',
  missed_call: 'Missed call',
  deposit_paid: 'Deposit paid',
  keyword: 'Keyword match',
}

// ─── Component ────────────────────────────────────────────────────────────────

interface RuleEditorSheetProps {
  open: boolean
  onClose: () => void
  onSaved: () => void
  rule?: AutoReplyRuleWithTemplate | null
  templates: MessageTemplate[]
}

export function RuleEditorSheet({
  open,
  onClose,
  onSaved,
  rule,
  templates,
}: RuleEditorSheetProps) {
  const isEdit = !!rule
  const [saving, setSaving] = useState(false)

  const [values, setValues] = useState<RuleFormValues>({
    trigger_type: 'new_inquiry',
    keyword: '',
    template_id: '',
    cooldown_minutes: 60,
    tone: 'casual',
    enabled: true,
  })

  const [errors, setErrors] = useState<Partial<Record<keyof RuleFormValues, string>>>({})

  useEffect(() => {
    if (open) {
      setErrors({})
      if (rule) {
        setValues({
          trigger_type: rule.trigger_type,
          keyword: rule.keyword ?? '',
          template_id: rule.template_id,
          cooldown_minutes: rule.cooldown_minutes,
          tone: rule.tone,
          enabled: rule.enabled,
        })
      } else {
        setValues({
          trigger_type: 'new_inquiry',
          keyword: '',
          template_id: templates[0]?.id ?? '',
          cooldown_minutes: 60,
          tone: 'casual',
          enabled: true,
        })
      }
    }
  }, [open, rule, templates])

  const set = <K extends keyof RuleFormValues>(key: K, value: RuleFormValues[K]) => {
    setValues((prev) => ({ ...prev, [key]: value }))
    setErrors((prev) => ({ ...prev, [key]: undefined }))
  }

  const validate = (): boolean => {
    const result = RuleFormSchema.safeParse(values)
    if (!result.success) {
      const newErrors: Partial<Record<keyof RuleFormValues, string>> = {}
      for (const issue of result.error.issues) {
        const field = issue.path[0] as keyof RuleFormValues
        newErrors[field] = issue.message
      }
      setErrors(newErrors)
      return false
    }
    if (values.trigger_type === 'keyword' && !values.keyword?.trim()) {
      setErrors((prev) => ({ ...prev, keyword: 'Keyword is required for keyword trigger' }))
      return false
    }
    return true
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    try {
      const payload = {
        trigger_type: values.trigger_type,
        keyword: values.trigger_type === 'keyword' ? (values.keyword ?? null) : null,
        template_id: values.template_id,
        cooldown_minutes: values.cooldown_minutes,
        tone: values.tone,
      }

      const res = isEdit
        ? await updateRuleAction({ id: rule.id, ...payload })
        : await createRuleAction(payload)

      if (!res.ok) {
        toast.error(res.error ?? 'Failed to save rule')
        return
      }

      toast.success(isEdit ? 'Rule updated' : 'Rule created')
      onSaved()
      onClose()
    } finally {
      setSaving(false)
    }
  }

  return (
    <ActionSheet
      open={open}
      onOpenChange={(v) => { if (!v) onClose() }}
      title={isEdit ? 'Edit auto-reply rule' : 'New auto-reply rule'}
      description="Automatically reply when a trigger condition is matched."
      width="sm"
      footer={
        <div className="flex gap-3 w-full">
          <Button variant="ghost" onClick={onClose} disabled={saving} className="flex-1 h-10">
            Cancel
          </Button>
          <Button onClick={() => void handleSave()} loading={saving} loadingLabel="Saving..." className="flex-1 h-10">
            {isEdit ? 'Save changes' : 'Create rule'}
          </Button>
        </div>
      }
    >
      <div className="space-y-5">
        {/* Trigger type */}
        <div className="space-y-1.5">
          <Label htmlFor="rule-trigger">Trigger</Label>
          <select
            id="rule-trigger"
            value={values.trigger_type}
            onChange={(e) => set('trigger_type', e.target.value as RuleFormValues['trigger_type'])}
            className="flex h-9 w-full rounded-md border border-border/60 bg-background px-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
          >
            {(Object.keys(TRIGGER_LABELS) as RuleFormValues['trigger_type'][]).map((t) => (
              <option key={t} value={t}>{TRIGGER_LABELS[t]}</option>
            ))}
          </select>
        </div>

        {/* Keyword input — only when trigger=keyword */}
        {values.trigger_type === 'keyword' && (
          <div className="space-y-1.5">
            <Label htmlFor="rule-keyword">Keyword</Label>
            <Input
              id="rule-keyword"
              value={values.keyword ?? ''}
              onChange={(e) => set('keyword', e.target.value)}
              placeholder="e.g. reschedule"
              aria-invalid={!!errors.keyword}
            />
            {errors.keyword && (
              <p className="text-xs text-destructive">{errors.keyword}</p>
            )}
          </div>
        )}

        {/* Template */}
        <div className="space-y-1.5">
          <Label htmlFor="rule-template">Reply template</Label>
          <select
            id="rule-template"
            value={values.template_id}
            onChange={(e) => set('template_id', e.target.value)}
            className="flex h-9 w-full rounded-md border border-border/60 bg-background px-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
          >
            <option value="">— Select a template —</option>
            {templates.map((tpl) => (
              <option key={tpl.id} value={tpl.id}>{tpl.name}</option>
            ))}
          </select>
          {errors.template_id && (
            <p className="text-xs text-destructive">{errors.template_id}</p>
          )}
        </div>

        {/* Cooldown */}
        <div className="space-y-1.5">
          <Label htmlFor="rule-cooldown">Cooldown (minutes)</Label>
          <Input
            id="rule-cooldown"
            type="number"
            min={0}
            max={1440}
            value={values.cooldown_minutes}
            onChange={(e) => set('cooldown_minutes', parseInt(e.target.value, 10) || 0)}
            aria-invalid={!!errors.cooldown_minutes}
          />
          <p className="text-[11px] text-muted-foreground">
            Minimum time between auto-replies per conversation.
          </p>
          {errors.cooldown_minutes && (
            <p className="text-xs text-destructive">{errors.cooldown_minutes}</p>
          )}
        </div>

        {/* Tone */}
        <div className="space-y-2">
          <Label>Tone</Label>
          <div className="flex gap-3">
            {(['casual', 'formal'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => set('tone', t)}
                className={`flex-1 rounded-lg border px-3 py-2 text-[13px] font-medium transition-colors ${
                  values.tone === t
                    ? 'border-foreground bg-foreground text-background'
                    : 'border-border text-muted-foreground hover:border-foreground/40'
                }`}
                aria-pressed={values.tone === t}
              >
                {t.charAt(0).toUpperCase() + t.slice(1)}
              </button>
            ))}
          </div>
        </div>

        {/* Enabled */}
        <div className="flex items-center justify-between py-1">
          <div>
            <p className="text-sm font-medium">Enabled</p>
            <p className="text-[11px] text-muted-foreground">Rule fires when active</p>
          </div>
          <Switch
            checked={values.enabled}
            onCheckedChange={(v) => set('enabled', v)}
            aria-label="Enable rule"
          />
        </div>
      </div>
    </ActionSheet>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { Plus, Pencil, Trash2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Switch } from '@/components/ui/switch'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { RuleEditorSheet } from './RuleEditorSheet'
import { toggleRuleAction, deleteRuleAction } from '@/app/(app)/messages/actions'
import type { MessageTemplate } from '@/lib/supabase/types'
import type { AutoReplyRuleWithTemplate } from '@/lib/messaging/queries'
import { useRouter } from 'next/navigation'

// ─── Trigger labels ───────────────────────────────────────────────────────────

function triggerLabel(rule: AutoReplyRuleWithTemplate): string {
  if (rule.trigger_type === 'keyword') return `Keyword: ${rule.keyword ?? ''}`
  const map: Record<string, string> = {
    new_inquiry: 'New inquiry',
    missed_call: 'Missed call',
    deposit_paid: 'Deposit paid',
  }
  return map[rule.trigger_type] ?? rule.trigger_type
}

// ─── Component ────────────────────────────────────────────────────────────────

interface AutoReplyRulesCardProps {
  rules: AutoReplyRuleWithTemplate[]
  templates: MessageTemplate[]
}

export function AutoReplyRulesCard({ rules: initialRules, templates }: AutoReplyRulesCardProps) {
  const router = useRouter()
  const [rules, setRules] = useState(initialRules)
  const [sheetOpen, setSheetOpen] = useState(false)
  const [editingRule, setEditingRule] = useState<AutoReplyRuleWithTemplate | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<AutoReplyRuleWithTemplate | null>(null)
  const [deleting, startDelete] = useTransition()
  const [togglingId, setTogglingId] = useState<string | null>(null)

  const openCreate = () => {
    setEditingRule(null)
    setSheetOpen(true)
  }

  const openEdit = (rule: AutoReplyRuleWithTemplate) => {
    setEditingRule(rule)
    setSheetOpen(true)
  }

  const handleToggle = async (rule: AutoReplyRuleWithTemplate) => {
    setTogglingId(rule.id)
    const res = await toggleRuleAction(rule.id, !rule.enabled)
    setTogglingId(null)
    if (res.ok) {
      setRules((prev) =>
        prev.map((r) => (r.id === rule.id ? { ...r, enabled: !r.enabled } : r)),
      )
    } else {
      toast.error(res.error ?? 'Failed to toggle rule')
    }
  }

  const handleDelete = () => {
    if (!deleteTarget) return
    startDelete(async () => {
      const res = await deleteRuleAction(deleteTarget.id)
      if (res.ok) {
        setRules((prev) => prev.filter((r) => r.id !== deleteTarget.id))
        toast.success('Rule deleted')
      } else {
        toast.error(res.error ?? 'Failed to delete rule')
      }
      setDeleteTarget(null)
    })
  }

  const handleSaved = () => {
    router.refresh()
  }

  return (
    <>
      <div className="rounded-xl border border-border bg-background shadow-card">
        <div className="px-6 pt-5 pb-4 border-b border-border/40 flex items-start justify-between gap-4">
          <div>
            <h3 className="text-sm font-bold text-foreground">Auto-replies</h3>
            <p className="text-[13px] text-muted-foreground mt-0.5">
              InkOS replies for you when a new inquiry, missed call, or keyword is detected.
            </p>
          </div>
          <Button
            size="sm"
            variant="outline"
            className="h-8 gap-1.5 shrink-0"
            onClick={openCreate}
          >
            <Plus className="h-3.5 w-3.5" aria-hidden="true" />
            Add rule
          </Button>
        </div>

        {rules.length === 0 ? (
          <div className="px-6 py-10 text-center">
            <p className="text-[13px] text-muted-foreground">
              No auto-replies configured. Add one to never miss an inquiry again.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-border/40">
            {rules.map((rule) => (
              <div key={rule.id} className="flex items-center gap-4 px-6 py-3.5">
                {/* Trigger + template info */}
                <div className="flex-1 min-w-0 space-y-0.5">
                  <p className="text-[13px] font-medium text-foreground">
                    {triggerLabel(rule)}
                  </p>
                  <p className="text-[11px] text-muted-foreground truncate">
                    {rule.template?.name ?? 'No template'} ·{' '}
                    {rule.cooldown_minutes} min cooldown ·{' '}
                    <span className="capitalize">{rule.tone}</span>
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 shrink-0">
                  <Switch
                    checked={rule.enabled}
                    onCheckedChange={() => void handleToggle(rule)}
                    disabled={togglingId === rule.id}
                    aria-label={rule.enabled ? 'Disable rule' : 'Enable rule'}
                  />
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                    aria-label="Edit rule"
                    onClick={() => openEdit(rule)}
                  >
                    <Pencil className="h-3.5 w-3.5" aria-hidden="true" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8 hover:text-destructive"
                    aria-label="Delete rule"
                    onClick={() => setDeleteTarget(rule)}
                  >
                    <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <RuleEditorSheet
        open={sheetOpen}
        onClose={() => setSheetOpen(false)}
        onSaved={handleSaved}
        rule={editingRule}
        templates={templates}
      />

      <AlertDialog open={!!deleteTarget} onOpenChange={(v) => { if (!v) setDeleteTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete rule?</AlertDialogTitle>
            <AlertDialogDescription>
              The auto-reply for &ldquo;{deleteTarget ? triggerLabel(deleteTarget) : ''}&rdquo; will be removed permanently.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { z } from 'zod'
import { toast } from 'sonner'
import { X } from 'lucide-react'
import { ActionSheet } from '@/components/shared/ActionSheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { createTemplateAction, updateTemplateAction } from '@/app/(app)/messages/actions'
import { slugify } from '@/lib/utils'
import type { MessageTemplate, MessageTemplateChannel, MessageTemplateCategory } from '@/lib/supabase/types'

// ─── Constants ────────────────────────────────────────────────────────────────

const CHANNEL_OPTIONS: { value: MessageTemplateChannel; label: string }[] = [
  { value: 'both', label: 'Both SMS + Email' },
  { value: 'sms', label: 'SMS only' },
  { value: 'email', label: 'Email only' },
]

const CATEGORY_OPTIONS: { value: MessageTemplateCategory; label: string }[] = [
  { value: 'aftercare', label: 'Aftercare' },
  { value: 'deposit', label: 'Deposit' },
  { value: 'booking', label: 'Booking' },
  { value: 'portfolio', label: 'Portfolio' },
  { value: 'reschedule', label: 'Reschedule' },
  { value: 'inquiry_reply', label: 'Inquiry reply' },
  { value: 'custom', label: 'Custom' },
]

const TOKENS = [
  '{{studio_name}}',
  '{{client_first_name}}',
  '{{booking_link}}',
  '{{portfolio_link}}',
  '{{aftercare_pdf_link}}',
] as const

const TOKEN_MOCK: Record<typeof TOKENS[number], string> = {
  '{{studio_name}}': 'Ink & Iron Studio',
  '{{client_first_name}}': 'Alex',
  '{{booking_link}}': 'https://inkos.app/book/ink-iron',
  '{{portfolio_link}}': 'https://inkos.app/portfolio/ink-iron',
  '{{aftercare_pdf_link}}': 'https://inkos.app/aftercare.pdf',
}

function renderPreview(body: string): string {
  let out = body
  for (const [token, value] of Object.entries(TOKEN_MOCK)) {
    out = out.replaceAll(token, value)
  }
  return out
}

// ─── Schema ───────────────────────────────────────────────────────────────────

const TemplateFormSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100),
  slug: z.string().min(1, 'Slug is required').max(100).regex(/^[a-z0-9-]+$/, 'Lowercase, numbers, hyphens only'),
  channel: z.enum(['sms', 'email', 'both']),
  category: z.enum(['aftercare', 'deposit', 'booking', 'portfolio', 'reschedule', 'inquiry_reply', 'custom']),
  body: z.string().min(1, 'Body is required').max(4000),
  trigger_keywords: z.array(z.string()),
})

type TemplateFormValues = z.infer<typeof TemplateFormSchema>

// ─── Component ────────────────────────────────────────────────────────────────

interface TemplateEditorSheetProps {
  open: boolean
  onClose: () => void
  onSaved: () => void
  template?: MessageTemplate | null
}

export function TemplateEditorSheet({
  open,
  onClose,
  onSaved,
  template,
}: TemplateEditorSheetProps) {
  const isEdit = !!template
  const [saving, setSaving] = useState(false)
  const bodyRef = useRef<HTMLTextAreaElement>(null)

  const [values, setValues] = useState<TemplateFormValues>({
    name: '',
    slug: '',
    channel: 'both',
    category: 'custom',
    body: '',
    trigger_keywords: [],
  })
  const [slugEdited, setSlugEdited] = useState(false)
  const [errors, setErrors] = useState<Partial<Record<keyof TemplateFormValues, string>>>({})
  const [keywordInput, setKeywordInput] = useState('')

  useEffect(() => {
    if (open) {
      setErrors({})
      setSlugEdited(false)
      setKeywordInput('')
      if (template) {
        setValues({
          name: template.name,
          slug: template.slug,
          channel: template.channel,
          category: template.category,
          body: template.body,
          trigger_keywords: template.trigger_keywords ?? [],
        })
        setSlugEdited(true) // don't overwrite on name change
      } else {
        setValues({ name: '', slug: '', channel: 'both', category: 'custom', body: '', trigger_keywords: [] })
      }
    }
  }, [open, template])

  const set = <K extends keyof TemplateFormValues>(key: K, value: TemplateFormValues[K]) => {
    setValues((prev) => {
      const next = { ...prev, [key]: value }
      if (key === 'name' && !slugEdited) {
        next.slug = slugify(value as string)
      }
      return next
    })
    setErrors((prev) => ({ ...prev, [key]: undefined }))
  }

  const insertToken = (token: string) => {
    const el = bodyRef.current
    if (!el) return
    const start = el.selectionStart
    const end = el.selectionEnd
    const current = values.body
    const next = current.slice(0, start) + token + current.slice(end)
    set('body', next)
    // restore focus + cursor after token
    requestAnimationFrame(() => {
      el.focus()
      el.setSelectionRange(start + token.length, start + token.length)
    })
  }

  const addKeyword = () => {
    const kw = keywordInput.trim()
    if (!kw || values.trigger_keywords.includes(kw)) return
    set('trigger_keywords', [...values.trigger_keywords, kw])
    setKeywordInput('')
  }

  const removeKeyword = (kw: string) => {
    set('trigger_keywords', values.trigger_keywords.filter((k) => k !== kw))
  }

  const validate = (): boolean => {
    const result = TemplateFormSchema.safeParse(values)
    if (!result.success) {
      const newErrors: Partial<Record<keyof TemplateFormValues, string>> = {}
      for (const issue of result.error.issues) {
        const field = issue.path[0] as keyof TemplateFormValues
        newErrors[field] = issue.message
      }
      setErrors(newErrors)
      return false
    }
    return true
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    try {
      const res = isEdit
        ? await updateTemplateAction({ id: template.id, ...values })
        : await createTemplateAction(values)

      if (!res.ok) {
        toast.error(res.error ?? 'Failed to save template')
        return
      }
      toast.success(isEdit ? 'Template updated' : 'Template created')
      onSaved()
      onClose()
    } finally {
      setSaving(false)
    }
  }

  return (
    <ActionSheet
      open={open}
      onOpenChange={(v) => { if (!v) onClose() }}
      title={isEdit ? 'Edit template' : 'New template'}
      description="Define a reusable reply you can insert with / in any conversation."
      width="lg"
      footer={
        <div className="flex gap-3 w-full">
          <Button variant="ghost" onClick={onClose} disabled={saving} className="flex-1 h-10">
            Cancel
          </Button>
          <Button onClick={() => void handleSave()} loading={saving} loadingLabel="Saving..." className="flex-1 h-10">
            {isEdit ? 'Save changes' : 'Create template'}
          </Button>
        </div>
      }
    >
      <div className="grid gap-5 lg:grid-cols-2">
        {/* Left: form fields */}
        <div className="space-y-4">
          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="tpl-name">Name <span className="text-destructive">*</span></Label>
            <Input
              id="tpl-name"
              value={values.name}
              onChange={(e) => set('name', e.target.value)}
              placeholder="Deposit request"
              aria-invalid={!!errors.name}
            />
            {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
          </div>

          {/* Slug */}
          <div className="space-y-1.5">
            <Label htmlFor="tpl-slug">Slug</Label>
            <Input
              id="tpl-slug"
              value={values.slug}
              onChange={(e) => { setSlugEdited(true); set('slug', e.target.value) }}
              placeholder="deposit-request"
              aria-invalid={!!errors.slug}
            />
            <p className="text-[11px] text-muted-foreground font-mono">
              /t/{values.slug || 'slug'}
            </p>
            {errors.slug && <p className="text-xs text-destructive">{errors.slug}</p>}
          </div>

          {/* Channel + Category row */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="tpl-channel">Channel</Label>
              <select
                id="tpl-channel"
                value={values.channel}
                onChange={(e) => set('channel', e.target.value as MessageTemplateChannel)}
                className="flex h-9 w-full rounded-md border border-border/60 bg-background px-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              >
                {CHANNEL_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="tpl-category">Category</Label>
              <select
                id="tpl-category"
                value={values.category}
                onChange={(e) => set('category', e.target.value as MessageTemplateCategory)}
                className="flex h-9 w-full rounded-md border border-border/60 bg-background px-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              >
                {CATEGORY_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Trigger keywords */}
          <div className="space-y-1.5">
            <Label htmlFor="tpl-keywords">Trigger keywords</Label>
            <div className="flex gap-2">
              <Input
                id="tpl-keywords"
                value={keywordInput}
                onChange={(e) => setKeywordInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addKeyword() } }}
                placeholder="Type keyword + Enter"
                className="flex-1"
              />
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={addKeyword}
                className="h-9"
                aria-label="Add keyword"
              >
                Add
              </Button>
            </div>
            {values.trigger_keywords.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {values.trigger_keywords.map((kw) => (
                  <Badge
                    key={kw}
                    variant="secondary"
                    className="gap-1 pr-1 text-[11px]"
                  >
                    {kw}
                    <button
                      type="button"
                      onClick={() => removeKeyword(kw)}
                      aria-label={`Remove keyword ${kw}`}
                      className="hover:text-destructive rounded-sm"
                    >
                      <X className="h-3 w-3" aria-hidden="true" />
                    </button>
                  </Badge>
                ))}
              </div>
            )}
          </div>

          {/* Body */}
          <div className="space-y-1.5">
            <Label htmlFor="tpl-body">Body <span className="text-destructive">*</span></Label>
            <Textarea
              id="tpl-body"
              ref={bodyRef}
              value={values.body}
              onChange={(e) => set('body', e.target.value)}
              rows={8}
              placeholder="Hi {{client_first_name}}, here's your deposit link..."
              className="resize-none font-mono text-[13px]"
              aria-invalid={!!errors.body}
            />
            {errors.body && <p className="text-xs text-destructive">{errors.body}</p>}

            {/* Token insert hints */}
            <div className="pt-1">
              <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-[0.08em] mb-1.5">
                Insert variable
              </p>
              <div className="flex flex-wrap gap-1.5">
                {TOKENS.map((token) => (
                  <button
                    key={token}
                    type="button"
                    onClick={() => insertToken(token)}
                    className="rounded border border-border bg-muted/30 px-2 py-0.5 font-mono text-[11px] text-muted-foreground hover:bg-muted transition-colors"
                    aria-label={`Insert ${token}`}
                  >
                    {token}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Right: preview */}
        <div className="space-y-1.5">
          <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-[0.08em]">
            Preview
          </p>
          <div className="rounded-xl border border-border bg-muted/20 p-4 min-h-[200px]">
            <p className="font-mono text-[13px] text-foreground whitespace-pre-wrap leading-relaxed">
              {values.body
                ? renderPreview(values.body)
                : <span className="text-muted-foreground/60 italic">Preview appears here as you type…</span>
              }
            </p>
          </div>
          <p className="text-[11px] text-muted-foreground">
            Variables shown with mock values. Actual values resolve at send time.
          </p>
        </div>
      </div>
    </ActionSheet>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { Plus, Pencil, Trash2, RefreshCw } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { ChannelIcon } from '@/components/messages/ChannelIcon'
import { TemplateEditorSheet } from './TemplateEditorSheet'
import { deleteTemplateAction, seedDefaultTemplatesAction } from '@/app/(app)/messages/actions'
import { useRouter } from 'next/navigation'
import type { MessageTemplate, MessageTemplateCategory } from '@/lib/supabase/types'

// ─── Category filter ──────────────────────────────────────────────────────────

const CATEGORY_FILTERS: { value: MessageTemplateCategory | 'all'; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'aftercare', label: 'Aftercare' },
  { value: 'deposit', label: 'Deposit' },
  { value: 'booking', label: 'Booking' },
  { value: 'portfolio', label: 'Portfolio' },
  { value: 'reschedule', label: 'Reschedule' },
  { value: 'inquiry_reply', label: 'Inquiry reply' },
  { value: 'custom', label: 'Custom' },
]

const CATEGORY_LABELS: Record<MessageTemplateCategory, string> = {
  aftercare: 'Aftercare',
  deposit: 'Deposit',
  booking: 'Booking',
  portfolio: 'Portfolio',
  reschedule: 'Reschedule',
  inquiry_reply: 'Inquiry reply',
  custom: 'Custom',
}

// ─── Component ────────────────────────────────────────────────────────────────

interface TemplatesTableProps {
  templates: MessageTemplate[]
}

export function TemplatesTable({ templates: initialTemplates }: TemplatesTableProps) {
  const router = useRouter()
  const [templates, setTemplates] = useState(initialTemplates)
  const [activeFilter, setActiveFilter] = useState<MessageTemplateCategory | 'all'>('all')
  const [sheetOpen, setSheetOpen] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<MessageTemplate | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<MessageTemplate | null>(null)
  const [deleting, startDelete] = useTransition()
  const [seeding, startSeed] = useTransition()

  const filtered =
    activeFilter === 'all'
      ? templates
      : templates.filter((t) => t.category === activeFilter)

  const openCreate = () => {
    setEditingTemplate(null)
    setSheetOpen(true)
  }

  const openEdit = (t: MessageTemplate) => {
    setEditingTemplate(t)
    setSheetOpen(true)
  }

  const handleDelete = () => {
    if (!deleteTarget) return
    startDelete(async () => {
      const res = await deleteTemplateAction(deleteTarget.id)
      if (res.ok) {
        setTemplates((prev) => prev.filter((t) => t.id !== deleteTarget.id))
        toast.success('Template deleted')
      } else {
        toast.error(res.error ?? 'Failed to delete template')
      }
      setDeleteTarget(null)
    })
  }

  const handleSeedDefaults = () => {
    startSeed(async () => {
      const res = await seedDefaultTemplatesAction()
      if (res.ok) {
        toast.success(
          res.data?.inserted === 0
            ? 'Default templates are already present'
            : `${res.data?.inserted ?? 0} default templates restored`,
        )
        router.refresh()
      } else {
        toast.error(res.error ?? 'Failed to restore defaults')
      }
    })
  }

  const handleSaved = () => {
    router.refresh()
  }

  return (
    <>
      <div className="rounded-xl border border-border bg-background shadow-card">
        {/* Header */}
        <div className="px-6 pt-5 pb-4 border-b border-border/40 flex items-start justify-between gap-4">
          <div>
            <h3 className="text-sm font-bold text-foreground">Templates</h3>
            <p className="text-[13px] text-muted-foreground mt-0.5">
              Saved replies you can insert with <kbd className="font-mono">/</kbd> in any conversation.
            </p>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <Button
              size="sm"
              variant="ghost"
              className="h-8 gap-1.5 text-muted-foreground"
              onClick={handleSeedDefaults}
              disabled={seeding}
              aria-label="Restore default templates"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${seeding ? 'animate-spin' : ''}`} aria-hidden="true" />
              Restore defaults
            </Button>
            <Button
              size="sm"
              variant="outline"
              className="h-8 gap-1.5"
              onClick={openCreate}
            >
              <Plus className="h-3.5 w-3.5" aria-hidden="true" />
              New template
            </Button>
          </div>
        </div>

        {/* Category filter pills */}
        <div className="px-6 py-3 border-b border-border/40 flex gap-1.5 flex-wrap">
          {CATEGORY_FILTERS.map((f) => (
            <button
              key={f.value}
              type="button"
              onClick={() => setActiveFilter(f.value)}
              className={`h-7 rounded-full px-3 text-[12px] font-medium transition-colors ${
                activeFilter === f.value
                  ? 'bg-foreground text-background'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
              }`}
              aria-pressed={activeFilter === f.value}
            >
              {f.label}
            </button>
          ))}
        </div>

        {/* Table */}
        {filtered.length === 0 ? (
          <div className="px-6 py-10 text-center">
            <p className="text-[13px] text-muted-foreground">
              {templates.length === 0
                ? 'No templates yet. Restore defaults to get started.'
                : 'No templates in this category.'}
            </p>
          </div>
        ) : (
          <div className="divide-y divide-border/40">
            {filtered.map((tpl) => (
              <div
                key={tpl.id}
                className="group flex items-start gap-4 px-6 py-3.5 hover:bg-foreground/[0.02] transition-colors"
              >
                {/* Name + default badge */}
                <div className="flex-1 min-w-0 space-y-0.5">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-[13px] font-medium text-foreground truncate">
                      {tpl.name}
                    </span>
                    {tpl.is_default && (
                      <span className="inline-flex items-center rounded border border-border px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
                        Default
                      </span>
                    )}
                    <Badge variant="secondary" className="h-5 text-[11px] capitalize">
                      {CATEGORY_LABELS[tpl.category]}
                    </Badge>
                  </div>

                  {/* Channel + keywords */}
                  <div className="flex items-center gap-2 mt-0.5">
                    <ChannelIcon channel={tpl.channel === 'both' ? 'all' : tpl.channel} className="h-3.5 w-3.5 text-muted-foreground" />
                    <span className="text-[11px] text-muted-foreground capitalize">{tpl.channel}</span>
                    {tpl.trigger_keywords.length > 0 && (
                      <span className="text-[11px] text-muted-foreground">
                        · {tpl.trigger_keywords.slice(0, 3).join(', ')}
                        {tpl.trigger_keywords.length > 3 ? ` +${tpl.trigger_keywords.length - 3}` : ''}
                      </span>
                    )}
                  </div>

                  {/* Body preview */}
                  <p className="mt-0.5 font-mono text-[12px] text-muted-foreground line-clamp-1">
                    {tpl.body.slice(0, 80)}{tpl.body.length > 80 ? '…' : ''}
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 pt-0.5">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    aria-label={`Edit template ${tpl.name}`}
                    onClick={() => openEdit(tpl)}
                  >
                    <Pencil className="h-3.5 w-3.5" aria-hidden="true" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 hover:text-destructive"
                    aria-label={`Delete template ${tpl.name}`}
                    onClick={() => setDeleteTarget(tpl)}
                  >
                    <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <TemplateEditorSheet
        open={sheetOpen}
        onClose={() => setSheetOpen(false)}
        onSaved={handleSaved}
        template={editingTemplate}
      />

      <AlertDialog open={!!deleteTarget} onOpenChange={(v) => { if (!v) setDeleteTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete template?</AlertDialogTitle>
            <AlertDialogDescription>
              &ldquo;{deleteTarget?.name}&rdquo; will be permanently removed. Any auto-reply rule using it will need a new template assigned.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

